/* Isolated interaction prototype: in-memory state, handcrafted examples, no API calls. */
(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const clone = v => JSON.parse(JSON.stringify(v));
  const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {
    library:'M4 4v16M8 4v16M12 5l4-1 4 15-4 1z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',layers:'m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
    feather:'M20 3C12 1 6 7 6 14l4 4c7 0 13-7 10-15zM3 21l11-11M6 14h6',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M15.5 8.5l-2 5-5 2 2-5z',moon:'M20 15.5A9 9 0 0 1 8.5 4 9 9 0 1 0 20 15.5z',people:'M9 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5v1',home:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8',
    search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0m-2 5 6 6',plus:'M12 5v14M5 12h14',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',copy:'M8 8h13v13H8zM4 16H3V3h13v1',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7v1',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bookmark:'M6 3h12v18l-6-4-6 4z',refresh:'M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 14 6M4 12a8 8 0 0 0 14 6',link:'m10 14 4-4M8 15l-2 2a3 3 0 0 1-4-4l4-4a3 3 0 0 1 4 0m4 0 2-2a3 3 0 0 1 4 4l-4 4a3 3 0 0 1-4 0',book:'M12 5v16M12 5C9 3 5 3 2 4v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1',edit:'m16 3 5 5-12 12-6 1 1-6zM13 6l5 5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-5'};
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
  const btn=(text,action,cls='',more='')=>`<button class="btn ${cls}" data-action="${action}" ${more}>${text}</button>`;
  const layer=id=>DEMO.layers.find(l=>l.id===id);
  const initialBook=()=>({primary:'womens_fiction',secondary:['fantasy'],story:['domestic_betrayal','werewolf','female_growth'],tones:[],settings:[],selection:clone(DEMO.recipes[0].selection),title:'',premise:'她曾以为，两个人一起守住的小镇就是他们的家。直到丈夫在群体庆典上，宣布了另一位同行者。我想写她如何重新找到自己的位置。',audience:'成熟女性读者',language:'英文',length:'随故事容量规划',constraints:''});
  const state={route:'library',elements:clone(DEMO.elements),recipes:clone(DEMO.recipes),selected:'betrayal',draft:clone(DEMO.elements[0]),editorTab:'guidance',filter:'all',status:'all',search:'',book:initialBook(),openLayer:'axis',workshopTab:'decision',round:0,choice:'',note:'',decisions:[],snapshot:null,busy:false,impact:'axis',previewGenerated:false,pending:null};
  const getElement=id=>state.elements.find(e=>e.id===id)||DEMO.elements.find(e=>e.id===id);
  const names=ids=>ids.map(id=>getElement(id)?.name||id).join('、');
  const label=id=>Object.values(H5_CATALOG.axes).flat().find(x=>x.id===id)?.label||id;
  const dirty=()=>JSON.stringify(state.draft)!==JSON.stringify(state.elements.find(e=>e.id===state.selected));
  const activeBook=()=>state.snapshot||state.book;
  const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
  let lastFocus=null,toastTimer;
  const app=$('#app'),dialog=$('#dialog');

  function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
  function openDialog(html,wide=false){lastFocus=document.activeElement;dialog.innerHTML=html;dialog.classList.toggle('wide',wide);if(!dialog.open)dialog.showModal();}
  function closeDialog(){dialog.close();lastFocus?.isConnected&&lastFocus.focus();}
  function dialogHead(title,description=''){return `<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="icon-button" data-action="close-dialog" aria-label="关闭弹窗">${icon('close')}</button></div>`;}
  function guard(next){if(state.route==='library'&&dirty()){state.pending=next;openDialog(dialogHead('这份资料有未保存的修改','离开前可以保存，也可以放弃本次编辑。')+`<div class="dialog-actions">${btn('继续编辑','close-dialog')}${btn('放弃修改','discard-pending')}${btn('保存并继续','save-pending','primary')}</div>`);}else next();}
  function navigate(route){guard(()=>{if(!['library','recipes','create','workshop','impact'].includes(route))route='library';state.route=route;history.replaceState(null,'','#'+route);render();window.scrollTo({top:0,behavior:'instant'});});}
  function header(title,sub,actions,eyebrow='创作资料库'){return `<header class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></header>`;}
  function libraryTabs(){return `<div class="top-tabs" role="tablist" aria-label="创作资料页面"><button role="tab" aria-selected="${state.route==='library'}" class="${state.route==='library'?'active':''}" data-route="library">创作元素 <span class="count">${state.elements.length}</span></button><button role="tab" aria-selected="${state.route==='recipes'}" class="${state.route==='recipes'?'active':''}" data-route="recipes">组合方案 <span class="count">${state.recipes.length}</span></button><span class="tab-hint">元素独立维护，在每本书里共同发挥作用</span></div>`;}
  function listContent(){const rows=state.elements.filter(e=>(state.filter==='all'||e.kind===state.filter)&&(state.status==='all'||e.status===state.status)&&[e.name,e.summary].join(' ').toLowerCase().includes(state.search.toLowerCase()));return DEMO.layers.map(l=>{const group=rows.filter(e=>e.kind===l.id);return group.length?`<section><div class="group-name"><span>${l.name}</span><span>${group.length}</span></div>${group.map(e=>`<button class="element-row ${e.id===state.selected?'active':''}" aria-pressed="${e.id===state.selected}" data-element="${e.id}"><span class="element-glyph">${icon(l.icon)}</span><span class="element-copy"><strong>${esc(e.name)}</strong><p>${esc(e.summary)}</p><small>${e.status==='draft'?'草稿':`v${e.version} · ${e.origin}`}</small></span></button>`).join('')}</section>`:'';}).join('')||'<div class="empty">没有匹配的元素<br><button class="text-button" data-action="clear-filters">清除筛选</button></div>';}
  function library(){return header('创作元素与方案','把你想写的故事，变成清楚、可复用的创作指导。',btn('试着组合一本新书 '+icon('arrow'),'go-create')+btn(icon('plus')+' 新建元素','new-element','primary'))+libraryTabs()+`<div class="library-layout"><aside class="element-list" aria-label="创作元素列表"><div class="searchbox">${icon('search')}<input class="field" type="search" id="element-search" value="${esc(state.search)}" placeholder="搜索元素、写作说明" aria-label="搜索创作元素"></div><div class="filters"><select id="layer-filter" aria-label="筛选创作层"><option value="all">全部创作层</option>${DEMO.layers.map(l=>`<option value="${l.id}" ${state.filter===l.id?'selected':''}>${l.name}</option>`).join('')}</select><select id="status-filter" aria-label="筛选状态"><option value="all">全部状态</option><option value="enabled" ${state.status==='enabled'?'selected':''}>已启用</option><option value="draft" ${state.status==='draft'?'selected':''}>草稿</option></select></div><div class="list-caption">${state.elements.length} 个元素 · 按创作层组织</div><div class="element-groups" id="element-groups">${listContent()}</div></aside><section class="editor" aria-label="元素编辑"><div class="editor-heading"><div class="editor-title"><span class="symbol">${icon(layer(state.draft.kind).icon)}</span><div><div class="editor-topline"><h2 id="editor-title">${esc(state.draft.name)}</h2>${badge(state.draft.status==='enabled'?'已启用':'草稿',state.draft.status==='enabled'?'':'amber')}</div><p>${layer(state.draft.kind).name} · ${state.draft.origin} · v${state.draft.version}</p></div></div><div class="editor-actions"><button class="btn small" data-action="copy-element">${icon('copy')}复制</button><button class="icon-button" data-action="delete-element" aria-label="删除当前元素">${icon('trash')}</button></div></div><div class="editor-tabs" role="tablist" aria-label="元素编辑标签">${[['guidance','写作指导'],['impact','输出影响'],['mapping','适用分类'],['versions','预览与版本']].map(([id,n])=>`<button role="tab" aria-selected="${state.editorTab===id}" data-editor-tab="${id}" class="${state.editorTab===id?'active':''}">${n}</button>`).join('')}</div><div class="editor-body" role="tabpanel">${editorContent()}</div><div id="savebar" class="savebar" ${dirty()?'':'hidden'}><div><strong>有未保存的修改</strong><br><small>保存后新建讨论可用；已有作品沿用原版本。</small></div><div class="row"><button class="text-button" data-action="discard">撤销修改</button>${btn('保存并启用','save','primary')}</div></div><div class="saved-note">${icon('shield')}已开始的作品始终保留自己的资料版本。</div></section></div>`;}
  function editorContent(){const e=state.draft;
    if(state.editorTab==='guidance')return `<div class="guidance-intro">${icon('spark')}<div><strong>写清故事的看点，保留不同的实现方式</strong><p>这份指导将影响骨架和正文。具体人物与情节，在每本书的头脑风暴中确定。</p></div></div><div class="form-grid form-section"><label><span class="form-label">元素名称</span><input class="field" data-draft="name" value="${esc(e.name)}" maxlength="60"></label><label><span class="form-label">所属创作层</span><select data-draft="kind">${DEMO.layers.map(l=>`<option value="${l.id}" ${e.kind===l.id?'selected':''}>${l.name}</option>`).join('')}</select></label></div><div class="form-section"><label class="form-label" for="element-summary">一句话说明它的作用</label><textarea id="element-summary" data-draft="summary" rows="2">${esc(e.summary)}</textarea></div><div class="form-section"><div class="form-section-head"><h3>读者应该获得什么</h3>${badge('阅读承诺','neutral')}</div>${e.promises.map((p,i)=>`<div class="editable-line"><span class="number">0${i+1}</span><textarea aria-label="阅读承诺 ${i+1}" data-promise="${i}" rows="2">${esc(p)}</textarea></div>`).join('')}</div><div class="form-section"><div class="form-section-head"><h3>${e.kind==='tone'?'怎样落到具体表达':'怎样让它推动故事'}</h3><span class="tiny muted">提供办法，不固定桥段</span></div>${e.mechanisms.map((m,i)=>`<details class="guide-card" ${i===0?'open':''}><summary><span class="tiny muted">0${i+1}</span>${esc(m.name)}</summary><div class="guide-inner"><label>核心写法<textarea data-mechanism="${i}" data-part="text" rows="2">${esc(m.text)}</textarea></label><label>保留变化空间<textarea data-mechanism="${i}" data-part="variation" rows="2">${esc(m.variation)}</textarea></label></div></details>`).join('')}</div><details class="guide-card"><summary>${icon('shield')}常见问题与使用边界</summary><div class="guide-inner"><textarea aria-label="使用边界" data-draft="boundary" rows="3">${esc(e.boundary)}</textarea></div></details>`;
    if(state.editorTab==='impact')return `<div class="section-title"><div><h3>选择「${esc(e.name)}」，作品会怎样变化？</h3><p>每一层都有输出要求，作用方式可以不同。</p></div></div><div class="timeline">${e.impacts.map((t,i)=>`<article class="timeline-item"><span class="number">0${i+1}</span><h3>${['骨架设计','章节与场景','正文表达'][i]}</h3><p>${esc(t)}</p></article>`).join('')}</div><div class="note-box">选择会贯穿设计和写作。骨架用具体节点说明作用，正文用实际场景与段落体现；模型不能自行忽略已选元素。</div><div class="section-title" style="margin-top:26px"><div><h3>在一本书里查看落实方式</h3><p>下面是独立的设计示例，不代表实际作品已通过评议。</p></div></div>${btn('查看五层落实示例 '+icon('arrow'),'go-impact','soft')}`;
    if(state.editorTab==='mapping')return `<div class="section-title"><div><h3>适用的 H5 分类</h3><p>${H5_CATALOG.version} · 和新建小说使用同一份字典</p></div></div><div class="note-box">用于推荐这份资料。这里的勾选不会替某一本书选择分类；本书发行分类在新建小说时单独确定。</div>${Object.entries(H5_CATALOG.axes).map(([key,entries])=>`<section class="mapping-group"><h3>${({primary_genres:'主类型',story_types:'故事类型',tones:'情绪与风格',settings:'故事背景'})[key]}</h3><div class="chips">${entries.map(x=>`<label class="chip ${e.mappings.includes(x.id)?'selected':''}"><input type="checkbox" data-map="${x.id}" ${e.mappings.includes(x.id)?'checked':''}>${esc(x.label)}</label>`).join('')}</div></section>`).join('')}`;
    return `<div class="section-title"><div><h3>模型将读到的创作指导</h3><p>预览当前编辑内容。这里只展示业务内容，发行适用分类不会变成剧情。</p></div>${badge('本页预览','neutral')}</div><pre class="preview-code">${esc(JSON.stringify({元素:e.name,创作层:layer(e.kind).name,作用:e.summary,阅读承诺:e.promises,实现方式:e.mechanisms.map(m=>({核心写法:m.text,变化空间:m.variation})),边界:e.boundary},null,2))}</pre><h3 style="margin-top:25px">版本记录</h3><div class="version-row">${badge('v'+e.version)}<span>${e.status==='enabled'?'当前启用版本':'当前草稿'}</span><small>演示资料</small></div><p class="helper">保存产生新版本；已开始的讨论保持其选择时的版本。</p>`;
  }
  function recipes(){return header('创作元素与方案','把常用的创作选择放在一起，每次写出不同的故事。',btn('组合一本新书 '+icon('arrow'),'go-create','primary'))+libraryTabs()+`<div class="recipes-intro"><div><h2>从一个组合，开始新的故事</h2><p>组合保存元素与用途，人物、事件和结局留给这一本书。</p></div>${badge('可调整每一层','neutral')}</div><div class="recipe-grid">${state.recipes.map(r=>`<article class="recipe-card"><div class="recipe-art ${r.color}"><span>${esc(r.tag)}</span><div class="motif">${icon(r.icon)}</div></div><div class="recipe-body"><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><div class="recipe-layers">${DEMO.layers.map(l=>`<div class="recipe-layer"><span>${l.name}</span><span>${names(r.selection[l.id])||'讨论时推荐'}</span></div>`).join('')}</div><div class="recipe-footer">${btn('用这个组合 '+icon('arrow'),'apply-recipe','primary small',`data-id="${r.id}"`)}<button class="text-button" data-action="recipe-detail" data-id="${r.id}">查看作用</button></div></div></article>`).join('')}</div><div class="route-help">${icon('info')}同一个组合可以形成不同的故事。模型会在头脑风暴中比较人物目标、冲突机制和关键选择。</div>`;}
  function steps(current){return `<div class="workflow-steps">${['基础设定','头脑风暴','骨架与启动'].map((t,i)=>`${i?'<span class="step-line"></span>':''}<span class="workflow-step ${i===current?'current':i<current?'done':''}"><i>${i<current?'✓':i+1}</i>${t}</span>`).join('')}<span class="flow-caption">先确定方向，再一起设计故事</span></div>`;}
  function summaryRows(b){return DEMO.layers.map(l=>`<div class="summary-layer"><span class="layer-dot">${icon(l.icon)}</span><div><small>${l.name}</small><strong class="${b.selection[l.id].length?'':'pending'}">${esc(names(b.selection[l.id])||'交给模型建议')}</strong></div></div>`).join('');}
  function summary(b){return `<div class="summary-header"><div class="eyebrow">这本书的创作设定</div><h3>你的选择，都将进入故事</h3><p>${Object.values(b.selection).filter(v=>v.length).length}/5 层已指定 · 其余在讨论中完善</p></div><div class="summary-layers">${summaryRows(b)}</div><div class="summary-bottom"><strong>${icon('link')} 从选择，到实际文字</strong><p>骨架说明每项选择如何起作用，章节安排承载场景，正文落实并接受阅读评议。</p><button class="text-button" data-action="save-recipe">${icon('bookmark')}保存为常用组合</button></div>`;}
  function layerChoice(l){const ids=state.book.selection[l.id],rows=state.elements.filter(e=>e.kind===l.id&&e.status==='enabled');return `<section class="layer-item ${state.openLayer===l.id?'open':''}"><button class="layer-toggle" aria-expanded="${state.openLayer===l.id}" data-open-layer="${l.id}"><span class="layer-index">0${DEMO.layers.indexOf(l)+1}</span><span class="layer-text"><strong>${l.name}</strong><small>${l.question}</small></span><span class="selected-copy">${esc(names(ids)||'待推荐')}</span>${icon('down')}</button>${state.openLayer===l.id?`<div class="layer-options"><div class="option-chips">${rows.map(e=>`<button class="option-chip ${ids.includes(e.id)?'selected':''}" aria-pressed="${ids.includes(e.id)}" data-book-element="${e.id}" data-kind="${l.id}">${ids.includes(e.id)?icon('check'):icon('plus')}${esc(e.name)}</button>`).join('')}</div><div class="layer-effect"><b>对作品的影响</b><br>${l.effect}${ids.length?`<br>${esc(ids.map(id=>getElement(id)?.summary).join(' '))}`:''}</div><label class="delegate"><input type="checkbox" data-delegate="${l.id}" ${!ids.length?'checked':''}>这一层还没想好，让模型给出建议</label>${l.id==='tone'?'<p class="helper">可同时选择阅读感受和表达方式；它们分别影响情绪安排与实际文字。</p>':''}</div>`:''}</section>`;}
  function create(){const b=state.book;return header('一起把故事想完整','先告诉我们你想写什么。具体人物、冲突与结局，在讨论中逐步确定。',btn(icon('layers')+' 从组合方案开始','go-recipes'),'新作品 · 创作准备')+steps(0)+`<div class="creation-grid"><section class="creation-main"><div class="row spread"><h2><span class="section-number">01</span>确定发行题材</h2><span class="tiny muted">与 H5 保持一致</span></div><div class="classification-card"><div class="form-grid"><label><span class="form-label">主分类 <span style="color:var(--violet)">*</span></span><select id="book-primary" data-book="primary"><option value="">请选择主分类</option>${H5_CATALOG.axes.primary_genres.map(x=>`<option value="${x.id}" ${b.primary===x.id?'selected':''}>${x.label}</option>`).join('')}</select></label><label><span class="form-label">阅读受众</span><input class="field" data-book="audience" value="${esc(b.audience)}"></label></div><div class="classification-tags">${[...b.secondary,...b.story,...b.tones,...b.settings].map(id=>`<span>${esc(label(id))}</span>`).join('')}<button class="text-button" data-action="publication" style="font-size:11px">调整发行标签</button></div><p class="helper">发行分类决定作品如何被发现，下面的创作设定决定故事怎样展开。</p></div><div class="row spread"><h2><span class="section-number">02</span>组合这本书的创作方向</h2>${badge('五层都影响输出')}</div><p class="helper">选你已经确定的部分。未确定的交给模型推荐，重要方向由你决定。</p><div class="layer-list">${DEMO.layers.map(layerChoice).join('')}</div><h2><span class="section-number">03</span>留下你的故事种子</h2><div class="form-section" style="margin-top:16px"><label class="form-label" for="book-premise">故事构想 <span class="muted small">· 可以是一段关系、一个场景或一个问题</span></label><textarea id="book-premise" data-book="premise" rows="4">${esc(b.premise)}</textarea></div><details class="advanced"><summary>更多偏好 · 书名、语言、篇幅与特别要求</summary><div class="form-grid"><label><span class="form-label">暂定书名</span><input class="field" data-book="title" value="${esc(b.title)}" placeholder="讨论后再决定也可以"></label><label><span class="form-label">正文语言</span><select data-book="language">${['英文','中文'].map(x=>`<option ${b.language===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="form-label">篇幅偏好</span><select data-book="length">${['随故事容量规划','偏短篇','偏长篇'].map(x=>`<option ${b.length===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="form-label">特别要求</span><input class="field" data-book="constraints" value="${esc(b.constraints)}" placeholder="例如：不加入新的感情救援者"></label></div></details></section><aside class="book-summary" id="book-summary" aria-label="本书创作设定摘要">${summary(b)}</aside></div><footer class="creation-footer"><p>第一轮会提出可比较的故事方向，供你选择和补充。<br><span class="tiny">设计稿将加载预设示例，不调用真实模型。</span></p><div class="row"><button class="text-button" data-route="library">返回资料库</button>${btn(icon('spark')+' 开始头脑风暴','start-workshop','primary',!b.primary?'disabled':'')}</div></footer>`;}
  function roundsForBook(){const rounds=clone(DEMO.rounds),b=activeBook();const branch=DEMO.storyBranches[state.decisions[0]?.choice];if(branch)branch.forEach((part,j)=>{const r=rounds[j+1];r.title=part.title;r.focus=part.focus;r.why='方案 A 延续已采用的主线，把新的发现、人物行动与后果连接起来；方案 B 提供另一种情感取舍。';r.options.forEach((o,i)=>{o.title=part.titles[i];o.story=part.stories[i];o.gain=i?'保留更复杂的关系空间。':'让行动与后果直接推动当前主线。';o.cost=i?'需要为犹疑和关系变化保留篇幅。':'人物必须承担选择带来的实际损失。';});});if(!b.selection.world.includes('werewolf')){for(const r of rounds)for(const o of r.options){o.story=o.story.replaceAll('群体庆典','家族聚会').replaceAll('巡守站','家族工坊').replaceAll('巡守','工坊').replaceAll('盟约','合作约定').replaceAll('群体印记','陌生钥匙').replaceAll('群体','家族');}rounds[0].why='方案 A 将亲密背叛、共同事业与个人成长联系起来，人物的行动会同时改变生活与关系。';if(b.selection.world.includes('horror')){rounds[0].options[0].story='家族聚会上，丈夫介绍了另一位女主人，亲友却像早已知道这件事。她回到卧室，发现自己的物件被悄悄归入客房。她开始追查：这段婚姻究竟从什么时候起，只有自己还相信它是真的？';rounds[0].options[1].story='丈夫受伤归来，口袋里多了一把陌生钥匙。她循着钥匙寻找真相，却发现每一个认识他们的人都提前准备好了同一种解释。';rounds[0].options[2].story='丈夫以照顾家人的名义要求她搬出旧宅。她试图寻求帮助，却发现电话、账户与熟人网络都已被悄悄重排。她要先找回一条能相信的信息来源。';}}
    return rounds;}
  function beatSummary(){const rounds=roundsForBook();return state.decisions.map((d,i)=>({name:rounds[i].stage,title:d.choice==='custom'?'作者提出的方向':d.choice==='delegate'?'采用模型推荐方向':rounds[i].options[Number(d.choice)].title,story:d.choice==='custom'?d.note:rounds[i].options[d.choice==='delegate'?0:Number(d.choice)].story,note:d.choice==='custom'?'':d.note}));}
  function choiceCards(r){return `<div class="choice-grid ${r.options.length===3?'three':''}" role="radiogroup" aria-label="本轮故事方案">${r.options.map((o,i)=>`<article class="choice-card ${state.choice===String(i)?'selected':''}"><label><div class="choice-label"><span><input type="radio" name="story-choice" value="${i}" ${state.choice===String(i)?'checked':''}>方案 ${String.fromCharCode(65+i)}</span>${badge(o.tag,i?'neutral':'')}</div><h3>${o.title}</h3><p class="choice-story">${o.story}</p></label><div class="choice-tradeoff"><div><p><b>看点</b> ${o.gain}</p><p><b>取舍</b> ${o.cost}</p></div></div><button class="choose-button" data-choice="${i}">${state.choice===String(i)?'✓ 已选择这个方向':'选择这个方向'}</button></article>`).join('')}</div>`;}
  function storyMap(){const beats=beatSummary();return `<div class="section-title"><div><h2>故事正在变得清楚</h2><p>已采用的决定会逐步连成全书；尚未讨论的部分保留待定。</p></div>${badge(beats.length+'/4 个宏观方向','neutral')}</div>${beats.length?`<div class="story-outline">${beats.map((b,i)=>`<article class="story-beat"><span class="number">0${i+1}</span><div><div class="row wrap"><h3>${b.name} · ${b.title}</h3>${badge('已采用','green')}</div><p>${esc(b.story)}</p>${b.note?`<p><b>作者补充：</b>${esc(b.note)}</p>`:''}</div></article>`).join('')}</div>`:'<div class="note-box">先选择本轮主线。模型建议只有在采用后，才会出现在这里。</div>'}${beats.length<4?`<div class="note-box" style="margin-top:17px">接下来会设计：${roundsForBook().slice(beats.length).map(r=>r.stage).join(' → ')}。完成关键决定后，再建议生成骨架。</div>`:''}`;}
  function workshop(){const complete=state.round>=4,r=roundsForBook()[Math.min(state.round,3)],b=activeBook();const main=state.workshopTab==='story'?storyMap():state.workshopTab==='requirements'?`<div class="section-title"><div><h2>五层选择，正在进入故事</h2><p>当前处于讨论阶段。以下为设计作用，正文尚未生成。</p></div></div><div class="story-outline">${DEMO.layers.map((l,i)=>`<article class="story-beat"><span class="number">0${i+1}</span><div><h3>${l.name} · ${esc(names(b.selection[l.id])||'待推荐')}</h3><p>${l.effect}</p><p>${b.selection[l.id].length?'已带入当前讨论。具体承载点将在骨架中展开。':'尚未指定，模型应在讨论中提出可选方向。'}</p></div></article>`).join('')}</div>`:complete?`<div class="ready-card"><div class="ready-icon">${icon('book')}</div>${badge('四轮讨论结果示意','green')}<h2 style="margin-top:12px">主要故事走向已明确</h2><p>你已选择主线、开篇、中段变化和结局回报。可以查看当前全书走线，再进入骨架设计。</p><div class="row" style="justify-content:center">${btn('查看骨架与落实预览 '+icon('arrow'),'generate-preview','primary')}${btn('继续调整故事','review-story')}</div></div>${storyMap()}`:`<div class="workshop-top"><h2>${r.title}</h2>${badge('单选 · '+r.options.length+' 个方向','neutral')}</div><p class="round-meta">第 ${state.round+1} 轮 · ${r.stage} · 本轮只决定一个重要问题</p><div class="focus-note"><strong>这次为什么讨论它</strong><br>${r.focus}</div>${choiceCards(r)}<p class="recommendation"><b>推荐理由：</b>${r.why}</p><div class="other-choices"><label><input type="radio" name="story-choice" value="custom" ${state.choice==='custom'?'checked':''}>我有另一种方向</label><label><input type="radio" name="story-choice" value="delegate" ${state.choice==='delegate'?'checked':''}>这一处采用模型推荐</label></div><form class="composer" id="decision-form"><label for="author-note">${state.choice==='custom'?'写下你的故事方向':'补充你的想法'} <span class="muted small">· ${state.choice==='custom'?'必填':'选填'}</span></label><textarea id="author-note" placeholder="例如：保留反击，但不要让所有邻居都站在她的对立面。" rows="2">${esc(state.note)}</textarea><div class="composer-foot"><p id="decision-hint">${state.choice?'选择和补充会一起提交，继续设计下一段故事。':'请选择一个方向，或明确采用模型推荐。'}</p><button id="decision-submit" class="btn primary" ${!state.choice||(state.choice==='custom'&&!state.note.trim())||state.busy?'disabled':''}>${state.busy?'<span class="spin"></span> 正在加载下一轮示例':'采用并继续推演 '+icon('arrow')}</button></div></form>`;
    return header('一起把故事想完整',b.title||'从你的五层设定出发，逐步设计一个属于这本书的故事。',btn(icon('edit')+' 修改基础设定','edit-book'),'头脑风暴 · 演示讨论')+steps(complete?2:1)+`<div class="top-tabs" role="tablist" aria-label="讨论视图">${[['decision',complete?'当前进展':'本轮决策'],['story','故事全貌'],['requirements','五层设定']].map(([id,t])=>`<button role="tab" aria-selected="${state.workshopTab===id}" class="${state.workshopTab===id?'active':''}" data-workshop-tab="${id}">${t}</button>`).join('')}<span class="tab-hint">预设交互示例 · 无模型调用</span></div><div class="workshop-layout"><section class="appear">${main}</section><aside class="story-sidebar"><h3>全书设计进展</h3><p>跟随关键决定推进，不按固定章节压缩故事。</p><div class="story-progress">${roundsForBook().map((r,i)=>`<div class="story-progress-step ${i<state.round?'done':i===state.round?'current':''}"><i></i>${r.stage}<small>${i<state.round?'已确定':i===state.round?'正在设计':'待讨论'}</small></div>`).join('')}</div><h3>本书选择</h3>${summaryRows(b)}${state.decisions.length?`<h3 style="margin-top:21px">目前的故事</h3><div class="mini-synopsis">${esc(beatSummary().map(x=>x.story).join(' ').slice(0,220))}${beatSummary().map(x=>x.story).join(' ').length>220?'…':''}</div>`:''}</aside></div>`;}
  function impact(){const l=layer(state.impact),e=DEMO.evidence[l.id];return header('每一个选择，都有故事里的落点','从骨架到正文，查看五层设定分别怎样发挥作用。',btn(icon('back')+' 返回讨论','go-workshop'),'设定落实 · 独立示例')+`<div class="note-box" style="margin-top:23px">这是「婚姻背叛＋狼人＋女性觉醒＋封闭小镇＋克制表达」的预设示例。用于展示落实方式，不是当前讨论的生成结果或质量评分。</div><div class="impact-grid"><nav class="impact-nav" aria-label="查看创作层落实">${DEMO.layers.map(x=>`<button data-impact="${x.id}" class="${x.id===l.id?'active':''}" aria-pressed="${x.id===l.id}">${icon(x.icon)}<span><strong>${x.name}</strong><small>${names(DEMO.recipes[0].selection[x.id])}</small></span></button>`).join('')}</nav><section class="impact-content appear"><div class="row spread wrap"><h2>${e.heading}</h2>${badge('落实方式示例')}</div><p class="helper">选择 → 具体设计 → 章节场景 → 真实文字</p><article class="evidence-block"><div class="evidence-head"><span>01</span><h3>骨架中怎样设计</h3>${badge('规划示例','neutral')}</div><p>${e.plan}</p></article><article class="evidence-block"><div class="evidence-head"><span>02</span><h3>哪些场景承担它</h3>${badge('场景示例','neutral')}</div><p>${e.scene}</p></article><article class="evidence-block"><div class="evidence-head"><span>03</span><h3>落到正文是什么样</h3>${badge('中文示意片段','neutral')}</div><p class="prose">${e.prose.split('\n').map(esc).join('<br>')}</p><div class="evidence-foot">体现在哪里：${e.why}</div></article><div class="impact-callout">实际作品需要基于已生成的正文检查。规划存在、段落被引用，都不能单独证明阅读效果已经达标。</div></section></div>`;}
  function render(){app.innerHTML=({library,recipes,create,workshop,impact})[state.route]();document.title=({library:'创作元素与方案',recipes:'常用组合方案',create:'新书五层设定',workshop:'一起把故事想完整',impact:'五层设定落实'})[state.route]+' · Novel OS 交互稿';document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));document.querySelectorAll('.preview-bar [data-route]').forEach(e=>e.classList.toggle('active',e.dataset.route===(state.route==='recipes'?'library':state.route)));document.querySelectorAll('.sidebar [data-route]').forEach(e=>{const active=e.dataset.route===(state.route==='recipes'?'library':state.route);e.classList.toggle('active',active);active?e.setAttribute('aria-current','page'):e.removeAttribute('aria-current');});}

  function refreshDirty(){const bar=$('#savebar');if(bar)bar.hidden=!dirty();const title=$('#editor-title');if(title)title.textContent=state.draft.name||'未命名元素';}
  function chooseElement(id){guard(()=>{state.selected=id;state.draft=clone(state.elements.find(x=>x.id===id));render();});}
  function saveElement(show=true){if(!state.draft.name.trim()||!state.draft.summary.trim()||!state.draft.promises.some(p=>p.trim())){toast('请填写名称、作用说明和至少一条阅读承诺。');return false;}const saved=clone(state.draft);saved.version=(state.elements.find(e=>e.id===saved.id)?.version||0)+1;saved.status='enabled';const idx=state.elements.findIndex(e=>e.id===saved.id);if(idx>=0)state.elements[idx]=saved;else state.elements.push(saved);state.draft=clone(saved);render();if(show)openDialog(`<div class="success-dialog"><div class="success-symbol">${icon('check')}</div><h2 id="dialog-title">已保存并启用</h2><p>「${esc(saved.name)}」已更新为 v${saved.version}。<br>已有作品继续使用原来的资料版本。</p>${btn('知道了','close-dialog','primary')}<p class="tiny">此操作仅保留在当前设计稿页面。</p></div>`);return true;}
  function publicationDialog(){const b=state.book;openDialog(dialogHead('本书的发行分类','来自 H5 标准字典；这里的选择属于本书，不改变元素资料。')+`<form id="publication-form"><label class="form-label" for="pub-primary">主分类 · 必选一项</label><select id="pub-primary" name="primary">${H5_CATALOG.axes.primary_genres.map(x=>`<option value="${x.id}" ${b.primary===x.id?'selected':''}>${x.label}</option>`).join('')}</select>${[['secondary','primary_genres','次分类 · 最多 2 项',b.secondary],['story','story_types','故事类型 · 最多 3 项',b.story],['tones','tones','情绪与风格 · 最多 3 项',b.tones],['settings','settings','故事背景 · 最多 2 项',b.settings]].map(([key,axis,title,values])=>`<div class="mapping-group"><h3>${title}</h3><div class="chips">${H5_CATALOG.axes[axis].map(x=>`<label class="chip ${values.includes(x.id)?'selected':''}"><input type="checkbox" name="${key}" value="${x.id}" ${values.includes(x.id)?'checked':''}>${esc(x.label)}</label>`).join('')}</div></div>`).join('')}<p id="pub-error" class="error-line" role="alert"></p><div class="dialog-actions">${btn('取消','close-dialog')}<button type="submit" class="btn primary">应用到本书</button></div></form>`,true);}
  function startWorkshop(){if(!state.book.primary){toast('请先选择 H5 主分类。');return;}const run=()=>{state.snapshot=clone(state.book);state.round=0;state.decisions=[];state.choice='';state.note='';state.workshopTab='decision';state.previewGenerated=false;navigate('workshop');toast('已加载第一轮示例方案，不会发起模型调用。');};if(state.decisions.length&&JSON.stringify(state.snapshot)!==JSON.stringify(state.book)){state.pending=run;openDialog(dialogHead('按新设定重新开始讨论？','本设计稿会清除刚才的演示决定，使用新设定开始。真实作品不会受到影响。')+`<div class="dialog-actions">${btn('继续修改','close-dialog')}${btn('重新开始演示','confirm-pending','primary')}</div>`);}else run();}
  function showNewElement(){openDialog(dialogHead('新建创作元素','先写清这份资料的作用，再完善看点和实现方式。')+`<form id="new-element-form" class="stack"><label><span class="form-label">元素名称</span><input class="field" name="name" placeholder="例如：信任修复" required maxlength="60"></label><label><span class="form-label">所属创作层</span><select name="kind">${DEMO.layers.map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select></label><label><span class="form-label">一句话作用</span><textarea name="summary" required rows="2" placeholder="它会怎样影响人物、故事或表达？"></textarea></label><div class="dialog-actions">${btn('取消','close-dialog')}<button class="btn primary">创建并编辑</button></div></form>`);}
  function setChoice(choice){state.choice=choice;const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector('input[name="story-choice"][value="'+choice+'"]')?.focus({preventScroll:true});}
  function syncSubmit(){const b=$('#decision-submit');if(b&&!state.busy)b.disabled=!state.choice||(state.choice==='custom'&&!state.note.trim());}
  const actions={
    'go-create':()=>navigate('create'),'go-recipes':()=>navigate('recipes'),'go-workshop':()=>navigate('workshop'),'go-impact':()=>{state.impact=state.draft.kind;navigate('impact');},
    'close-dialog':closeDialog,'save':()=>saveElement(),'discard':()=>{state.draft=clone(state.elements.find(e=>e.id===state.selected));render();},
    'discard-pending':()=>{const fn=state.pending;state.pending=null;state.draft=clone(state.elements.find(e=>e.id===state.selected));closeDialog();fn?.();},
    'save-pending':()=>{if(saveElement(false)){const fn=state.pending;state.pending=null;closeDialog();fn?.();toast('已保存并启用；切换到下一页面。');}},
    'confirm-pending':()=>{const fn=state.pending;state.pending=null;closeDialog();fn?.();},
    'clear-filters':()=>{state.search='';state.filter='all';state.status='all';render();},
    'new-element':()=>guard(showNewElement),
    'copy-element':()=>guard(()=>{const e=clone(state.draft);e.id='custom_'+Date.now();e.name+=' · 副本';e.origin='自定义';e.version=0;e.status='draft';state.elements.push(clone(e));state.selected=e.id;state.draft={...e,version:1};state.editorTab='guidance';render();toast('副本已创建，修改后可保存并启用。');}),
    'delete-element':()=>openDialog(dialogHead('删除「'+esc(state.draft.name)+'」？','它将从新建作品的可选资料中移除。已有作品与保存的组合示例保留引用版本。')+`<div class="dialog-actions">${btn('取消','close-dialog')}${btn('删除元素','confirm-delete','danger')}</div>`),
    'confirm-delete':()=>{state.elements=state.elements.filter(e=>e.id!==state.selected);if(!state.elements.length)state.elements.push({id:'blank',kind:'axis',name:'新的创作元素',summary:'请编辑这份资料。',promises:[''],mechanisms:[],boundary:'',mappings:[],version:1,status:'draft',origin:'自定义',impacts:['待填写','待填写','待填写']});state.selected=state.elements[0].id;state.draft=clone(state.elements[0]);closeDialog();render();toast('元素已删除。历史示例保持原有引用。');},
    'publication':publicationDialog,'start-workshop':startWorkshop,'edit-book':()=>{navigate('create');toast('可以编辑基础设定，点击开始时再确认是否重新推导。');},
    'save-recipe':()=>openDialog(dialogHead('保存为常用组合','只保存五层选择与发行分类，不固定本书的人物、情节和结局。')+`<form id="recipe-form"><label class="form-label" for="recipe-name">组合名称</label><input id="recipe-name" class="field" name="name" required maxlength="60" placeholder="给这组创作方向起个名字"><div class="recipe-layers">${DEMO.layers.map(l=>`<div class="recipe-layer"><span>${l.name}</span><span>${esc(names(state.book.selection[l.id])||'讨论时推荐')}</span></div>`).join('')}</div><div class="dialog-actions">${btn('取消','close-dialog')}<button class="btn primary">保存组合</button></div></form>`),
    'apply-recipe':button=>{const r=state.recipes.find(x=>x.id===button.dataset.id);state.book={...state.book,primary:r.primary,secondary:clone(r.secondary),story:clone(r.story),selection:clone(r.selection),tones:[],settings:[]};if(r.id==='house_recipe')state.book.premise='一段婚姻出现裂缝后，她发现熟悉的家人都在隐瞒同一件事。我希望她靠自己的行动查明真相，不加入超自然力量。';else if(r.id==='life_recipe')state.book.premise='她发现丈夫背叛了共同生活的承诺。我想写她怎样在小镇里重新建立属于自己的生活，不让新的恋人替她解决所有问题。';else state.book.premise=initialBook().premise;navigate('create');toast('组合已带入，可以逐层调整。');},
    'recipe-detail':button=>{const r=state.recipes.find(x=>x.id===button.dataset.id);openDialog(dialogHead(esc(r.name),'每一层独立发挥作用，组合不会固定一份故事大纲。')+`<div class="stack">${DEMO.layers.map(l=>`<div><h4>${l.name} · ${esc(names(r.selection[l.id])||'讨论时推荐')}</h4><p class="helper">${l.effect}</p></div>`).join('')}</div><div class="dialog-actions">${btn('关闭','close-dialog')}${btn('使用这个组合','use-dialog-recipe','primary',`data-id="${r.id}"`)}</div>`);},
    'use-dialog-recipe':b=>{closeDialog();actions['apply-recipe'](b);},
    'review-story':()=>{state.workshopTab='story';render();toast('可查看全书决定；如需重做演示，可修改基础设定。');},
    'generate-preview':()=>{state.previewGenerated=true;openDialog(dialogHead('骨架交付预览','这里展示已采用的演示决定。没有生成文件，也没有启动正文。')+`<div class="story-outline">${beatSummary().map((b,i)=>`<div class="story-beat"><span class="number">0${i+1}</span><div><h3>${esc(b.title)}</h3><p>${esc(b.story)}</p>${b.note?`<p>作者补充：${esc(b.note)}</p>`:''}</div></div>`).join('')}</div><div class="dialog-actions">${btn('返回讨论','close-dialog')}${btn('查看独立的五层落实示例','open-impact-example','primary')}</div>`,true);},
    'open-impact-example':()=>{closeDialog();navigate('impact');},
    'reset':()=>openDialog(dialogHead('重置当前演示？','清除本页编辑、保存的示例组合和讨论决定，恢复初始设计稿。')+`<div class="dialog-actions">${btn('取消','close-dialog')}${btn('重置演示','confirm-reset','primary')}</div>`),
    'confirm-reset':()=>{history.replaceState(null,'','#library');location.reload();}
  };
  document.addEventListener('click',event=>{const route=event.target.closest('[data-route]');if(route){navigate(route.dataset.route);return;}const action=event.target.closest('[data-action]');if(action){actions[action.dataset.action]?.(action);return;}const el=event.target.closest('[data-element]');if(el){chooseElement(el.dataset.element);return;}const tab=event.target.closest('[data-editor-tab]');if(tab){state.editorTab=tab.dataset.editorTab;render();return;}const open=event.target.closest('[data-open-layer]');if(open){state.openLayer=state.openLayer===open.dataset.openLayer?'':open.dataset.openLayer;render();return;}const pick=event.target.closest('[data-book-element]');if(pick){const {kind,bookElement:id}=pick.dataset;const ids=state.book.selection[kind];state.book.selection[kind]=ids.includes(id)?ids.filter(x=>x!==id):kind==='tone'?[...ids,id]:[id];render();return;}const choice=event.target.closest('[data-choice]');if(choice&&!state.busy){setChoice(choice.dataset.choice);return;}const wtab=event.target.closest('[data-workshop-tab]');if(wtab){state.workshopTab=wtab.dataset.workshopTab;render();return;}const impact=event.target.closest('[data-impact]');if(impact){state.impact=impact.dataset.impact;render();}});
  document.addEventListener('input',event=>{const t=event.target;if(t.id==='element-search'){state.search=t.value;$('#element-groups').innerHTML=listContent();}if(t.dataset.draft){state.draft[t.dataset.draft]=t.value;refreshDirty();}if(t.dataset.promise!==undefined){state.draft.promises[Number(t.dataset.promise)]=t.value;refreshDirty();}if(t.dataset.mechanism!==undefined){state.draft.mechanisms[Number(t.dataset.mechanism)][t.dataset.part]=t.value;refreshDirty();}if(t.dataset.book){state.book[t.dataset.book]=t.value;if(t.dataset.book==='primary'){state.book.secondary=state.book.secondary.filter(id=>id!==t.value);$('.creation-footer .primary').disabled=!t.value;}}if(t.id==='author-note'){state.note=t.value;syncSubmit();}});
  document.addEventListener('change',event=>{const t=event.target;if(t.id==='layer-filter'){state.filter=t.value;$('#element-groups').innerHTML=listContent();}if(t.id==='status-filter'){state.status=t.value;$('#element-groups').innerHTML=listContent();}if(t.dataset.map){state.draft.mappings=t.checked?[...new Set([...state.draft.mappings,t.dataset.map])]:state.draft.mappings.filter(id=>id!==t.dataset.map);t.closest('.chip').classList.toggle('selected',t.checked);refreshDirty();}if(t.dataset.delegate){state.book.selection[t.dataset.delegate]=t.checked?[]:state.elements.filter(e=>e.kind===t.dataset.delegate&&e.status==='enabled').slice(0,1).map(e=>e.id);render();}if(t.name==='story-choice'&&!state.busy)setChoice(t.value);if(dialog.contains(t)&&t.type==='checkbox')t.closest('.chip')?.classList.toggle('selected',t.checked);});
  document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;
    if(form.id==='new-element-form'){const f=new FormData(form),kind=f.get('kind');const e={id:'custom_'+Date.now(),name:f.get('name').trim(),kind,summary:f.get('summary').trim(),version:0,status:'draft',origin:'自定义',promises:[''],mechanisms:[{name:'核心写法',text:'',variation:''}],boundary:'',mappings:[],impacts:['在骨架中明确本元素怎样发挥作用。','安排承载这些作用的章节与场景。','在实际文字中体现，并引用内容核验。']};state.elements.push(clone(e));state.selected=e.id;state.draft={...clone(e),version:1};state.editorTab='guidance';state.filter='all';state.status='all';state.search='';closeDialog();state.route='library';history.replaceState(null,'','#library');render();toast('补充阅读承诺和核心写法后，即可保存启用。');}
    if(form.id==='publication-form'){const f=new FormData(form);const p={primary:f.get('primary'),secondary:f.getAll('secondary'),story:f.getAll('story'),tones:f.getAll('tones'),settings:f.getAll('settings')};const error=p.secondary.includes(p.primary)?'主分类与次分类不可重复。':p.secondary.length>2||p.story.length>3||p.tones.length>3||p.settings.length>2?'所选标签超过数量上限，请减少对应分类。':p.story.includes('sweet_romance')&&p.story.includes('dark_romance')?'甜蜜浪漫与黑暗浪漫不能同时作为发行类型。':'';if(error){$('#pub-error').textContent=error;return;}Object.assign(state.book,p);closeDialog();render();toast('本书发行分类已更新；创作元素保持原选择。');}
    if(form.id==='recipe-form'){const name=new FormData(form).get('name').trim();if(!name)return;state.recipes.push({id:'recipe_'+Date.now(),name,tag:'我的组合方案',description:'由当前五层选择保存。新作品仍会在讨论中确定自己的故事。',icon:'bookmark',color:'blue',primary:state.book.primary,secondary:clone(state.book.secondary),story:clone(state.book.story),selection:clone(state.book.selection)});openDialog(`<div class="success-dialog"><div class="success-symbol">${icon('check')}</div><h2 id="dialog-title">组合已保存</h2><p>「${esc(name)}」已出现在组合方案中。<br>仅在本次设计稿演示中保留。</p>${btn('知道了','close-dialog','primary')}</div>`);}
    if(form.id==='decision-form'){if(state.busy||!state.choice||(state.choice==='custom'&&!state.note.trim()))return;state.busy=true;const decision={choice:state.choice,note:state.note};render();setTimeout(()=>{state.decisions.push(decision);state.round++;state.choice='';state.note='';state.busy=false;if(state.route==='workshop'){render();window.scrollTo({top:150,behavior:'smooth'});}toast('已保存选择和补充，加载'+(state.round<4?'下一轮预设示例。':'全书设计结果示例。'));},650);}
  });
  document.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key)||!event.target.matches('[role="tab"]'))return;const tabs=[...event.target.closest('[role="tablist"]').querySelectorAll('[role="tab"]')],idx=tabs.indexOf(event.target),next=tabs[(idx+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length];event.preventDefault();const label=next.textContent;next.click();[...document.querySelectorAll('[role="tab"]')].find(t=>t.textContent===label)?.focus();});
  window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(['library','recipes','create','workshop','impact'].includes(route))navigate(route);});
  state.route=['library','recipes','create','workshop','impact'].includes(location.hash.slice(1))?location.hash.slice(1):'library';
  render();
})();
